# 滑动窗口。达到子串最大长度或某一字母多了时收缩；当前字母dic中有空余且未达最大长度时扩张
class Solution:
    def getAnagram(self,p:str):
        dic={}
        for i in p:
            if i in dic:
                dic[i]+=1
            else:
                dic[i]=1
        return dic
    def findAnagrams(self, s: str, p: str) -> list[int]:
        dic=self.getAnagram(p)
        dic_copy=dic.copy()
        fast,slow=0,0
        result=[]
        while fast<len(s):
            if s[fast] in dic:
                dic[s[fast]]-=1
                while dic[s[fast]]<0:
                    dic[s[slow]]+=1
                    slow+=1
            else:
                fast+=1
                slow=fast
                dic=dic_copy.copy() # !!!python万物皆对象，一定要是=dic_copy.copy()
                # 若直接=dic_copy《=》二者指向一块区域，下次改dic也会把dic_copy也改了！
                # 所以得再拷贝一块dic_copy.copy()给dic
                continue
            if fast-slow+1==len(p):
                result.append(slow)
                dic[s[slow]] += 1
                slow+=1
                fast+=1
            else:
                fast+=1
        return result

if __name__ == '__main__':
    s = Solution()
